import os
import re
import hmac
import hashlib
import ipaddress
import urllib.parse
from flask import Flask, request, jsonify, abort
import requests as http_requests
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32).hex())

# Allowed webhook targets (internal microservices)
ALLOWED_HOSTS = [
    'notifications.internal.svc',
    'analytics.internal.svc',
    'billing.internal.svc',
    'logging.internal.svc',
]

BLOCKED_IP_RANGES = [
    ipaddress.ip_network('127.0.0.0/8'),
    ipaddress.ip_network('10.0.0.0/8'),
    ipaddress.ip_network('172.16.0.0/12'),
    ipaddress.ip_network('192.168.0.0/16'),
    ipaddress.ip_network('169.254.0.0/16'),
]

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            abort(401)
        expected = hmac.new(
            app.config['SECRET_KEY'].encode() if isinstance(app.config['SECRET_KEY'], str) else app.config['SECRET_KEY'],
            b'api-key-v1',
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(api_key, expected):
            abort(403)
        return f(*args, **kwargs)
    return decorated


def validate_url_scheme(url):
    """Ensure URL uses HTTPS scheme only."""
    parsed = urllib.parse.urlparse(url)
    if parsed.scheme != 'https':
        return False
    return True


def validate_host_allowlist(url):
    """Check that the URL's host is in our allowlist."""
    parsed = urllib.parse.urlparse(url)
    hostname = parsed.hostname
    if hostname is None:
        return False
    if hostname not in ALLOWED_HOSTS:
        return False
    return True


def validate_no_private_ip(url):
    """Ensure resolved IP is not in private ranges."""
    parsed = urllib.parse.urlparse(url)
    hostname = parsed.hostname
    try:
        addr = ipaddress.ip_address(hostname)
        for network in BLOCKED_IP_RANGES:
            if addr in network:
                return False
    except ValueError:
        # Not an IP literal, hostname will be resolved by the HTTP client
        pass
    return True


def sanitize_path(path):
    """Remove dangerous path components."""
    # Remove any null bytes
    path = path.replace('\x00', '')
    # Normalize multiple slashes
    path = re.sub(r'/+', '/', path)
    # Must start with /
    if not path.startswith('/'):
        path = '/' + path
    return path


def build_webhook_url(base_url, endpoint_path):
    """Construct the final webhook URL from validated base and path.

    The base_url has been validated against the allowlist.
    The endpoint_path is the specific API endpoint to call.
    """
    # Ensure base doesn't end with slash
    base = base_url.rstrip('/')
    # Sanitize the path
    path = sanitize_path(endpoint_path)
    # Construct final URL
    final_url = base + path
    return final_url


@app.route('/api/v1/webhooks/send', methods=['POST'])
@require_api_key
def send_webhook():
    """Send a webhook notification to an internal service.

    Expects JSON body with:
    - service_url: Base URL of the target service (must be in allowlist)
    - endpoint: The API endpoint path to call
    - payload: The webhook payload data
    """
    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    service_url = data.get('service_url', '')
    endpoint = data.get('endpoint', '')
    payload = data.get('payload', {})

    # Validate the service URL
    if not validate_url_scheme(service_url):
        return jsonify({'error': 'Only HTTPS URLs are allowed'}), 400

    if not validate_host_allowlist(service_url):
        return jsonify({'error': 'Host not in allowlist'}), 403

    if not validate_no_private_ip(service_url):
        return jsonify({'error': 'Private IP addresses are blocked'}), 403

    # Validate endpoint path format
    if not isinstance(endpoint, str) or len(endpoint) > 200:
        return jsonify({'error': 'Invalid endpoint'}), 400

    if not re.match(r'^[a-zA-Z0-9/_.-]+$', endpoint):
        return jsonify({'error': 'Endpoint contains invalid characters'}), 400

    # Build the final URL
    final_url = build_webhook_url(service_url, endpoint)

    # Send the webhook
    try:
        resp = http_requests.post(
            final_url,
            json=payload,
            timeout=5,
            allow_redirects=False,
            headers={'Content-Type': 'application/json'}
        )
        return jsonify({
            'status': 'sent',
            'response_code': resp.status_code
        }), 200
    except http_requests.exceptions.RequestException as e:
        return jsonify({'error': 'Webhook delivery failed', 'detail': str(e)}), 502


@app.route('/api/v1/webhooks/test', methods=['POST'])
@require_api_key
def test_webhook():
    """Test connectivity to a webhook endpoint without sending payload."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    service_url = data.get('service_url', '')
    endpoint = data.get('endpoint', '')

